{
  "technical_and_design_decisions": [
    "For the Spark Streaming processor implementation (U5), we will leverage Spring XD's existing module extension points to ensure compatibility with the XD runtime, and provide both Java/Lambda and Scala implementations as separate, interchangeable module options for users.",
    "For Windows build and test support (U3, U4), Windows Server 2019 will be used as the baseline OS, as it is a long-term support release compatible with the Java 17+ requirement for Spring XD 1.1.",
    "For the Kafka upgrade (U7), we will preserve backward compatibility for all existing Kafka module configuration properties to avoid breaking changes for users with existing data pipelines.",
    "For the SHDP upgrade (U8), we will align the SHDP version with the Spring XD 1.1 dependency management BOM to ensure consistent transitive dependency versions across all modules.",
    "For the 1.0 to 1.1 migration (U1), migration tooling will prioritize support for the most common custom module types (sources, processors, sinks) first, with an extensible design to support additional module types in future releases."
  ],
  "assumptions": [
    "The development team has full access to the Spring XD source code repository, AWS EC2 console for provisioning Windows instances, and the project's CI/CD infrastructure.",
    "Existing Spring XD acceptance tests require only minor adjustments (e.g., path separators, line ending handling) to run on Windows, with no need for full test rewrites.",
    "The Pig script sample will use open-source, publicly available sample Pig scripts to avoid licensing restrictions, and will be compatible with Spring XD 1.1's built-in Pig module support.",
    "The Kafka SI GA release and SHDP GA release are fully compatible with Spring XD 1.1's core requirements (Java 17+, Spring 6 baseline).",
    "The reference guide PDF is generated from the project's existing Asciidoctor documentation source, so updating the copyright year only requires a single string change and a standard documentation build process.",
    "Existing community-contributed custom module porting guides for Spring XD 1.0 to 1.1 are available as a baseline, so no new porting documentation needs to be created from scratch for common module types."
  ],
  "activities": [
    {
      "activity_id": "A1",
      "activity_name": "Update Spring XD core to 1.1 baseline",
      "activity_description": "Align core Spring XD framework code, dependency management, and core module implementations with the 1.1 release requirements to establish a stable base for all other increment work.",
      "most_likely_effort": 5
    },
    {
      "activity_id": "A2",
      "activity_name": "Develop custom module migration tooling and porting guides",
      "activity_description": "Create automated migration scripts for common custom module (source, processor, sink) patterns, and update existing porting documentation to help users migrate their 1.0 custom modules to the 1.1 baseline.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "A3",
      "activity_name": "Create Pig script integration sample and reference documentation",
      "activity_description": "Develop a working end-to-end sample of a Pig script integrated with Spring XD, including configuration steps, deployment instructions, and explanation of how the Pig job interacts with XD sources and sinks.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "A4",
      "activity_name": "Configure Windows build support for Spring XD",
      "activity_description": "Update the project's build configuration to support Windows OS, resolve Windows-specific path and file permission issues, and validate that the full Spring XD project can be built successfully on a Windows machine.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "A5",
      "activity_name": "Provision Windows EC2 test environment",
      "activity_description": "Set up a Windows Server 2019 EC2 instance, install required dependencies (Java 17, build tools, Spring XD runtime), configure network security groups, and validate instance accessibility for testing.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A6",
      "activity_name": "Execute acceptance test suite on Windows environment",
      "activity_description": "Run the full Spring XD acceptance test suite on the provisioned Windows EC2 instance, identify and fix Windows-specific test failures, and document test pass/fail status.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "A7",
      "activity_name": "Configure CI build for Windows acceptance tests",
      "activity_description": "Set up a CI pipeline job to automatically provision the Windows EC2 environment, run the acceptance test suite, and report test results on a scheduled or code change trigger basis.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "A8",
      "activity_name": "Implement Java/Lambda Spark Streaming processor module",
      "activity_description": "Develop a Spring XD processor module for Spark Streaming using Java 17 and lambda expressions, including unit tests, integration tests, and usage documentation for the module.",
      "most_likely_effort": 5
    },
    {
      "activity_id": "A9",
      "activity_name": "Implement Scala Spark Streaming processor module",
      "activity_description": "Develop a Scala-based version of the Spark Streaming processor module for Spring XD, ensuring compatibility with the Java variant, including unit tests, integration tests, and usage documentation.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "A10",
      "activity_name": "Update reference guide copyright year",
      "activity_description": "Locate the copyright notice in the reference guide Asciidoctor source, update the year from 2014 to 2015, rebuild the PDF output, and validate the change is reflected correctly.",
      "most_likely_effort": 0.5
    },
    {
      "activity_id": "A11",
      "activity_name": "Backport Kafka XD changes to Spring Integration Kafka",
      "activity_description": "Identify all Kafka XD-specific customizations, bug fixes, and feature additions in the Spring XD Kafka module, port these changes to the Spring Integration Kafka codebase, and validate the ported changes work as expected.",
      "most_likely_effort": 6
    },
    {
      "activity_id": "A12",
      "activity_name": "Upgrade Spring Integration Kafka to SI GA release",
      "activity_description": "Update Spring XD's Kafka module dependencies to the SI Kafka GA release, resolve any compatibility issues, and run regression tests to validate Kafka module functionality.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "A13",
      "activity_name": "Upgrade SHDP to GA release",
      "activity_description": "Update Spring XD's SHDP module dependencies to the latest SHDP GA release, resolve compatibility issues with the XD runtime and other modules, and run regression tests for SHDP-related functionality (HDFS, Hive, etc.).",
      "most_likely_effort": 4
    }
  ],
  "reported_total": {
    "most_likely_effort": 46.5
  }
}

